package com.railway.service;
import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class BookingServiceTest {@Test void rejectsEmptyPassengerListBeforeDatabase(){assertThrows(IllegalArgumentException.class,()->new BookingService().reserve(1,1,LocalDate.now(),List.of()));}@Test void rejectsTooManyPassengersBeforeDatabase(){var ps=java.util.Collections.nCopies(7,new BookingService.Passenger("Asha Sharma",25,"FEMALE"));assertThrows(IllegalArgumentException.class,()->new BookingService().reserve(1,1,LocalDate.now(),ps));}@Test void rejectsInvalidPassengerBeforeDatabase(){assertThrows(IllegalArgumentException.class,()->new BookingService().reserve(1,1,LocalDate.now(),List.of(new BookingService.Passenger("<x>",20,"OTHER"))));}}
